import{_ as t,a as o}from"./chunks/1b748864de58ed9ba856.CW6ZiGHB.js";import{_ as n,o as a,c as i,a5 as r}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"The Power Of Being Alone (How To Be Yourself)","description":"","frontmatter":{"title":"The Power Of Being Alone (How To Be Yourself)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-power-of-being-alone-how-to-be-yourself.md","filePath":"en/letters/the-power-of-being-alone-how-to-be-yourself.md"}'),s={name:"en/letters/the-power-of-being-alone-how-to-be-yourself.md"};function h(l,e,p,u,d,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="the-power-of-being-alone-how-to-be-yourself" tabindex="-1">The Power Of Being Alone (How To Be Yourself) <a class="header-anchor" href="#the-power-of-being-alone-how-to-be-yourself" aria-label="Permalink to &quot;The Power Of Being Alone (How To Be Yourself)&quot;">​</a></h1><p>Dan Koe · 2022-10-29 · <a href="https://thedankoe.com/letters/the-power-of-being-alone-how-to-be-yourself/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-power-of-being-alone-how-to-be-yourself">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/VKxv79VSJa8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>“Be yourself!”</p><p>How annoying has that advice gotten?</p><p>Want to start writing? Just be yourself!</p><p>Want to start a personal brand? Be yourself!</p><p>Want to land a hot date? Be yourself!</p><p>It’s good advice, but not to the masses. They don’t understand what it really means to “be themselves.” Why?</p><p>Because they are somebody else, and they are viewing the world through that lens, not the one they created.</p><p>They went to school and unconsciously adopted personality traits, bad habits, and a notion of what’s possible in this life.</p><p>They went to college with a fresh start, but went through another round of conditioning, layering over their being once more.</p><p>They got a job and accepted the company’s goals as their own. The unconscious misalignment leads to dread, despair, and the death of a soul that leaves a robotic, animalistic corpse of a human being that lives in a perpetual state of survival. A slave to the external world.</p><p>When the external aligns with the internal, that is, when the goals you create align with who you really are, the unconscious sends resources to your conscious mind to execute on those goals faster.</p><p>The unconscious mind can manage 11 million bits of information per second while the conscious mind only 40-50 bits of information. Imagine how much untapped power you are sitting on. All you need to do is tap into it.</p><p>In previous letters, we’ve discussed how manual labor, specialization, and earning with your time is not sustainable.</p><p>Robots that perform specific tasks are just that, robots. They are being automated out left and right.</p><p>The future belongs to those that can leverage their creative power. The power of their mind.</p><p>But, if you try to leverage a mind that was created by the external world, you will simply be joining a different kind of rat race.</p><p>We want originality, personality, and wisdom.</p><p>We want to have visionary ideas that change people’s lives for the better.</p><p>That’s what we are talking about today. Let’s dive in.</p><h2 id="existence-is-relationship" tabindex="-1">Existence Is Relationship <a class="header-anchor" href="#existence-is-relationship" aria-label="Permalink to &quot;Existence Is Relationship&quot;">​</a></h2><blockquote><p>In a world where there are no eyes, the sun would not be light. And in a world where there were no soft skins, rocks would not be hard, nor in a world where there were no muscles would they be heavy. Existence is relationship, and you are smack in the middle of it. – Alan Watts</p></blockquote><p><em>In a world where there are no others, the self would not exist.</em></p><p><em>Your identity – or “the self” – can only exist when you make a distinction between you and everything around you</em>_._</p><p><img src="'+t+'" alt=""></p><p>This is what spirituality, non-duality, and Buddhism are pointing toward. Their aim is to make you realize that the self is not separate from the universe, it is the universe.</p><p>The goal of those teachings, and enlightenment as a whole, is the end of suffering.</p><p>Suffering happens when you fail to recognize the infinite intelligence (interconnectedness) that life is. Suffering happens when you fail to zoom out and see the big picture.</p><p><em><strong>Suffering happens when you see the world from the lens of comparison.</strong></em> You zoom in on the difference between self and other.</p><p><em><strong>Enjoyment happens when you see the world from the lens of connection.</strong></em> You zoom out and create a holistic perspective. You highlight the similarities, why those matter, and appreciate the intelligence that connects everything the untrained eye would see as separate.</p><p>This is “love” by many spiritual teachings, even though I feel that term confuses the modern world, which is why I use the words “enjoyment” and “appreciation.”</p><blockquote><p>Two steps to happiness:\\</p><p>Zoom in on what&#39;s important.<br> Zoom out from everything else.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1521057414203727873?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 2, 2022</a></p></blockquote><p>When you are zoomed in on things that don’t matter, your mind is zoomed in, meaning it is closed-minded. You prevent your mind from seeing any further than what fills the content of your consciousness.</p><p>Narrow focus is great for things like productivity and purpose, when you are actively pursuing a meaningful goal, but this is not the case for most people.</p><p><img src="'+o+'" alt=""></p><p>Most people are in a perpetual state of stress-induced narrow (contracted) focus. A negative thought pops into their head and that immerses all of their attention. They can’t see beyond the thought itself. The thought becomes their world, and the importance of the world ceases to exist.</p><p>What does this have to do with “being yourself?”</p><p>Here’s a tweet I wrote the other day:</p><blockquote><p>People love to say “be yourself,” but tend to forget that it took your entire life to get to this point of not being yourself.\\</p><p>It’s going to take thousands of hours to reprogram your mind to act from a place of consistent authenticity.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1584837675877638147?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">October 25, 2022</a></p></blockquote><p>You see, since the day you popped into this world, your conscious mind has been interpreting the sensory information it receives and storing it in memory.</p><p>This is necessary to be able to operate in the external world, but isn’t it crazy how this works? How do we share the same language? How do we have a specific amount of career paths to pursue? I have many questions. We could live in an entirely different reality, and I would argue people on polar ends of the Earth do, we just don’t understand their perspective.</p><p>The point is, by the time you are 18, “yourself” is created by your environment. Humans are creatures of habit, your mind forms grooves with time, like the Grand Canyon with water, called neural networks.</p><p>Through societal, cultural, and social conditioning, and if left unconscious, you have zero control over “being yourself.”</p><p>You are quite literally a product of the external world.</p><p>Social media has created the problem of over-socialization, and quite frankly, socialization makes you stupid. When an unconfident mind is exposed to hundreds of thousands of confident thoughts, advice, and opinions, your mind tries to latch on to those.</p><p>Soon enough, you’ll find yourself speaking like the echo chamber you surround yourself in. You’ll be thinking the thoughts of others, not your own thoughts.</p><p>I find it funny that many people would cringe at the thought of being with their friends for an extended period of time, but will log on to social media (1000s of friends telling you what to do) and act like it isn’t different, or worse.</p><p><em><strong>I’m not saying any of this is bad, and there is no immediate solution. I’m saying this to spread awareness, as that is the first step to improvement. You cannot improve what you are not aware of. You cannot remove what you are not aware of.</strong></em></p><p>Don’t just blindly trust what I’m saying here.</p><p>As you are going about this week, try to catch yourself being someone else.</p><p>Notice the words you pick up, and if you want to be using those words.</p><p>Notice what decisions you make, and if those decisions are influenced by someone else (online or offline).</p><p>And if they are influenced by others, are those decisions beneficial to your goals, or theirs? Where is the “money” flowing?</p><p>“Who wrote the software in your head, and are you sure you want it running there?” – Master Of Twitter (and attention) Elon Musk</p><h2 id="the-power-of-being-alone-how-to-be-yourself-1" tabindex="-1">The Power Of Being Alone (How To Be Yourself) <a class="header-anchor" href="#the-power-of-being-alone-how-to-be-yourself-1" aria-label="Permalink to &quot;The Power Of Being Alone (How To Be Yourself)&quot;">​</a></h2><p><em>You can’t be yourself if you’re never alone with yourself.</em></p><p>As with everything, this requires balance. Balance does not mean split down the middle. Balance means a conscious effort to prevent either extreme from taking over.</p><p>If your goal is to make a dent on this world, you will have to expose yourself to other people. You will have to provide the most value to other people.</p><p>The problem with over-socialization: your thoughts, writing, and work are not unique, original, or novel. Meaning, you will get the same results as everyone else.</p><p>This is especially important for knowledge workers, value creators, and really anyone that doesn’t want to trade money for time. Time and manual labor is a dead end (that doesn’t mean it isn’t a viable option for beginners). You have to earn an income with creative ideas, solutions, and content.</p><p>How are you going to do that when you are putting out the same information as everyone in your niche?</p><p>If you want to reverse the effects of being on social media, keeping up with the trendiest joke for your friend group, or meeting new people that you think are better than you (so you adopt aspects of their personality) – you have to <strong>make time for being alone.</strong></p><p>What’s the first step to “being yourself?”</p><p>Prioritizing yourself.</p><p>Being selfish.</p><blockquote><p>Selflessness requires selfish values:\\</p><p>– Self-control<br> – Self-reliance<br> – Self-reflection<br> – Self-education<br> – Self-awareness<br> – Self-employment<br> – Self-management\\</p><p>It&#39;s impossible to be selfless when you are dependent on others for your survival.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1585981967199240192?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">October 28, 2022</a></p></blockquote><p>I realize that I left an important point out of that list: <strong>self-experimentation.</strong></p><p>Take it on yourself to “figure it out.”</p><p><em>Don’t outsource your health to convenience.</em></p><p><em>Don’t outsource your thinking to social media.</em></p><p><em>Don’t outsource your career to the school system.</em></p><p>Treat your life as a science project. The essence of science is trial and error. Try everything and eliminate what doesn’t work. Be your own personal trainer. Be your own business mentor. Be your own therapist.</p><p>What do you do during your alone time?</p><p>Here are a few of my favorite methods for thinking clear, critical, and deep:</p><h3 id="_1-go-on-a-contemplative-walk" tabindex="-1">1) Go On A Contemplative Walk <a class="header-anchor" href="#_1-go-on-a-contemplative-walk" aria-label="Permalink to &quot;1) Go On A Contemplative Walk&quot;">​</a></h3><p>If you aren’t going on at least one daily walk, do you even follow me? What are you doing brother / sister? This isn’t only about “getting your steps in.” This is about:</p><ul><li>Living longer</li><li>Having creative ideas</li><li>Stress regulation (to prevent unconscious narrow focus)</li><li>Getting away from your screen</li><li>A distractionless timeblock for listening to that book you’ve been putting off</li><li>Writing content (ideas just flow better when you’re walking)</li></ul><p>Do you want me to go on? I could list off 10 more reasons.</p><p>GO. ON. A. WALK.</p><p>But, when you do, contemplate.</p><p>Hold one idea in your head and let your mind dance with it. Let thoughts trigger thoughts. Sit back and observe. Open your focus so wide that everything in your sensory field is held lightly in your conscious awareness. Lean in to all 5 senses and let your subconscious take over.</p><ul><li>Contemplate your vision.</li><li>Contemplate who you want to become.</li><li>Contemplate why you aren’t who you want to become.</li><li>Contemplate who you are and if you created that identity (and if not, who did?)</li><li>Contemplate the idea that stuck out to you in something you read.</li><li>Contemplate why you hold specific beliefs and if those are closing your mind off to futher discovery.</li></ul><p>Dig deep. Don’t let the ego trap you in a cycle of compulsive negative thinking. Question.</p><p>When your mind is stuck, move.</p><p><strong>2) Weekly Self-Reflection</strong></p><p>Nobody knows exactly what they want in the future. It’s literally impossible. There are infinite possibilities of what could happen in the next second.</p><p>We can “guess” with a mission, vision, and goals to follow — if we create them, rather than being assigned them — and those are helpful for guiding us in a positive direction.</p><p>But, you only know what will happen when it happens, and once it happens, we tend to forget about it and repeat mistakes left unconscious.</p><p>Self-reflection allows you to know with absolute certainty whether your actions were conducive or detrimental to your future.</p><p>I like to think of this as the “art of doing whatever you want.”</p><p>You have to do what you want, even if it’s for shallow reasons, and self-reflect to become conscious of the detriments of your actions.</p><p><em>You will never make the perfect decision. You just get better at making imperfect decisions.</em></p><p><strong>3) Write To Clarify Your Thoughts</strong></p><blockquote><p>If you can think, and speak, and write, you are absolutely deadly. Nothing can get in your way.</p><p>— Dr Jordan B Peterson (@jordanbpeterson) <a href="https://twitter.com/jordanbpeterson/status/1465735961279700993?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 30, 2021</a></p></blockquote><p>Few ideas can be held at the “top of mind.”</p><p>Your conscious brain can only process a certain amount of information. It can only hold a specific amount of content in its conscious awareness.</p><p>Meaning, most of the things you think, read, and want to remember can’t be given much attention. You have to note them down and clarify the thoughts in your head with the written word.</p><blockquote><p>If you don&#39;t have ideas, read.\\</p><p>If you have ideas, but can&#39;t articulate them, write.\\</p><p>If you have ideas, and have the clarity to execute, build.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1584932451251519490?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">October 25, 2022</a></p></blockquote><p>Now, I’m a fan of efficiency.</p><p>So if you plan to <a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">build a one-person business</a>, the way you will attract customers is through writing.</p><p>Every single person you look up to or buy from is a writer, whether they like to think of themselves as that or not.</p><p>Writing is how you build leverage for a future going digital.</p><p>Doesn’t it make sense to pair writing for clarity and writing for an income?</p><p>If you’re looking to learn how, check out <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">The 2 Hour Writer.</a></p><p><strong>4) Question The Story Your Ego Fabricates</strong></p><p>None of this is easy. It’s extremely difficult.</p><p>It doesn’t help that it all sounds so mystical either. This isn’t a “step-by-step system to make a million dollars in 30 days.”</p><p>That’s an external game. It was constructed by man and the schematics are readily available.</p><p>This is an internal game. You will have to dance, fight, and battle with the ego over years and years. I’m 10+ years in this game and it never ends (but it does get easier). It is infinite unless you opt out of external games to become a monk. Not many feel the pull to do that, and I don’t believe it to be necessary, as the battle is what makes the story interesting.</p><p>Watch where your mind goes as you are going about your life.</p><p>This practice is easiest on social media.</p><p>As you are scrolling on Twitter, notice how your mind will start a conversation with the post you read. What story is it creating out of nowhere? Why is it making you angry or happy? What aspects of that fabricated story do you agree or disagree with those points?</p><p>Extract the essence of the post you read (or anything you see in life) as it is.</p><p>And stay aware of how your mind will fill in the blanks to create its own picture.</p><p>When you become aware, zoom out as far as you can. Gain meta-perspective and appreciate the situation for what it is.</p><p><strong>– Dan Koe</strong></p><p><strong>What Happened This Week</strong></p><p>The latest YouTube video, The One Person Business Model (How To Productize Yourself, went absolutely bonkers. It beat all of my prior videos analytics by 10X. I think we are finally hitting the “nothing happens, then everything happens” point in this journey.</p><p><a href="https://youtu.be/BZ2nSULolKI" target="_blank" rel="noreferrer">Watch it here.</a></p><p>In Modern Mastery, we had a workshop on making your ideas stick in the head of your readers with Max Bernstein. I will personally be incorporating the writing tips into my process.</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Readers can join for $5</a></p><p>Digital Economics is off to a great start with 130+ students in this cohort. I’m stoked to see what results we can get for everyone building leverage on the internet with their interests and personality.</p>',124)])])}const m=n(s,[["render",h]]);export{w as __pageData,m as default};
